// Core tests: the 9 literal core cases from fixtures.json (expected values
// taken verbatim from the file, never generated by the product), plus
// boundary, validation, and property cases. The extra success literals
// below were derived independently from the SPEC's rules with an exact
// rational (Fraction) scratch calculation, not from the product code.

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/ac.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  sizeUnit: "ping",
  area: "10",
  occupants: "2",
  westSun: "false",
  topFloor: "false",
  largeWindows: "false",
  kitchenHeat: "false",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("legal maxima: 300 ping and 1000 m2 both compute and are over range", () => {
  assert.deepEqual(run({ ...base, area: "300" }), {
    ok: true,
    result: {
      ping: "300.00",
      baseKcalH: 150000,
      adjustmentPct: 0,
      requiredKcalH: 150000,
      requiredBtuH: 595200,
      requiredKw: "174.42",
      tonnageRuleOfThumb: "60.0",
      recommendedModelKw: null,
      nextModelKw: null,
      modelOverRange: true,
    },
  });
  assert.deepEqual(run({ ...base, sizeUnit: "m2", area: "1000" }), {
    ok: true,
    result: {
      ping: "302.50",
      baseKcalH: 151249,
      adjustmentPct: 0,
      requiredKcalH: 151249,
      requiredBtuH: 600157,
      requiredKw: "175.87",
      tonnageRuleOfThumb: "60.5",
      recommendedModelKw: null,
      nextModelKw: null,
      modelOverRange: true,
    },
  });
});

test("legal minima: 0.5 ping and 1 m2 recommend the smallest size", () => {
  assert.deepEqual(run({ ...base, area: "0.5" }).result, {
    ping: "0.50",
    baseKcalH: 250,
    adjustmentPct: 0,
    requiredKcalH: 250,
    requiredBtuH: 992,
    requiredKw: "0.29",
    tonnageRuleOfThumb: "0.1",
    recommendedModelKw: "2.2",
    nextModelKw: "2.8",
    modelOverRange: false,
  });
  assert.deepEqual(run({ ...base, sizeUnit: "m2", area: "1" }).result, {
    ping: "0.30",
    baseKcalH: 151,
    adjustmentPct: 0,
    requiredKcalH: 151,
    requiredBtuH: 600,
    requiredKw: "0.18",
    tonnageRuleOfThumb: "0.1",
    recommendedModelKw: "2.2",
    nextModelKw: "2.8",
    modelOverRange: false,
  });
});

test("adjustments add, never compound: all switches on with 30 occupants is +129%", () => {
  const outcome = run({
    ...base,
    occupants: "30",
    westSun: "true",
    topFloor: "true",
    largeWindows: "true",
    kitchenHeat: "true",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.adjustmentPct, 129);
  assert.equal(outcome.result.requiredKcalH, 11450);
  assert.equal(outcome.result.requiredBtuH, 45434);
  assert.equal(outcome.result.requiredKw, "13.31");
  assert.equal(outcome.result.tonnageRuleOfThumb, "4.6");
});

test("occupants 1 or 2 add nothing and never subtract", () => {
  assert.deepEqual(run({ ...base, occupants: "1" }).result, run(base).result);
  assert.equal(run({ ...base, occupants: "3" }).result.adjustmentPct, 3);
});

test("exact kW of exactly 10.0 recommends 10.0 with no next size; a hair above is over range", () => {
  const exact = run({ ...base, area: "17.2" });
  assert.equal(exact.ok, true);
  assert.equal(exact.result.requiredKw, "10.00");
  assert.equal(exact.result.recommendedModelKw, "10.0");
  assert.equal(exact.result.nextModelKw, null);
  assert.equal(exact.result.modelOverRange, false);
  const over = run({ ...base, area: "17.21" });
  assert.equal(over.ok, true);
  assert.equal(over.result.requiredKw, "10.01");
  assert.equal(over.result.recommendedModelKw, null);
  assert.equal(over.result.nextModelKw, null);
  assert.equal(over.result.modelOverRange, true);
});

test("just over the limits: 300.01 ping and 31 occupants are RANGE; a 9-unit area is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, area: "300.01" }), { code: "RANGE", field: "area", row: null });
  assert.deepEqual(errorOf({ ...base, sizeUnit: "m2", area: "1000.01" }), {
    code: "RANGE",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "0.49" }), { code: "RANGE", field: "area", row: null });
  assert.deepEqual(errorOf({ ...base, sizeUnit: "m2", area: "0.99" }), {
    code: "RANGE",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "31" }), {
    code: "RANGE",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "0" }), {
    code: "RANGE",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "area",
    row: null,
  });
});

test("grammar: area decimals, occupants integers, enum membership", () => {
  assert.deepEqual(errorOf({ ...base, area: "1." }), {
    code: "DECIMAL_FORMAT",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: ".5" }), {
    code: "DECIMAL_FORMAT",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "01" }), {
    code: "DECIMAL_FORMAT",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "10 " }), {
    code: "DECIMAL_FORMAT",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "１０" }), {
    code: "DECIMAL_FORMAT",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "2.5" }), {
    code: "INTEGER_FORMAT",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "02" }), {
    code: "INTEGER_FORMAT",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sizeUnit: "PING" }), {
    code: "ENUM",
    field: "sizeUnit",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, westSun: "yes" }), {
    code: "ENUM",
    field: "westSun",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, kitchenHeat: "True" }), {
    code: "ENUM",
    field: "kitchenHeat",
    row: null,
  });
});

test("empty fields are EMPTY and lone surrogates are UNICODE, per field", () => {
  assert.deepEqual(errorOf({ ...base, area: "" }), { code: "EMPTY", field: "area", row: null });
  assert.deepEqual(errorOf({ ...base, sizeUnit: "" }), {
    code: "EMPTY",
    field: "sizeUnit",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "\uD800" }), {
    code: "UNICODE",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, area: "\uDC00" }), {
    code: "UNICODE",
    field: "area",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(
    errorOf({ ...base, sizeUnit: "sqft", area: "0.4", occupants: "31" }),
    { code: "ENUM", field: "sizeUnit", row: null },
  );
  assert.deepEqual(errorOf({ ...base, area: "0.4", occupants: "31", westSun: "yes" }), {
    code: "RANGE",
    field: "area",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, occupants: "31", westSun: "yes" }), {
    code: "RANGE",
    field: "occupants",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, westSun: "yes", topFloor: "yes" }), {
    code: "ENUM",
    field: "westSun",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.area;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, area: 10 }), schema);
  assert.deepEqual(errorOf(["10"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("10"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "area", {
    enumerable: true,
    get() {
      return "10";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("property: removing any single adjustment never increases the required kcal/h", () => {
  const full = {
    ...base,
    area: "12.34",
    occupants: "7",
    westSun: "true",
    topFloor: "true",
    largeWindows: "true",
    kitchenHeat: "true",
  };
  const fullResult = run(full).result;
  for (const field of ["westSun", "topFloor", "largeWindows", "kitchenHeat"]) {
    const reduced = run({ ...full, [field]: "false" }).result;
    assert.ok(reduced.requiredKcalH <= fullResult.requiredKcalH, `${field} removal increased load`);
    assert.ok(reduced.adjustmentPct < fullResult.adjustmentPct);
  }
  const fewerPeople = run({ ...full, occupants: "2" }).result;
  assert.ok(fewerPeople.requiredKcalH <= fullResult.requiredKcalH);
});

test("property: a recommended size is always at or above the displayed required kW minus rounding", () => {
  // The recommendation compares the exact kW; the display rounds to 2
  // decimals, so the size may trail the display by at most half a display
  // unit (0.005 kW) — never more.
  for (const area of ["0.5", "1", "2.3", "4.82", "8.6", "10", "15", "17.2", "20"]) {
    const result = run({ ...base, area }).result;
    if (result.recommendedModelKw === null) {
      assert.equal(result.modelOverRange, true);
      continue;
    }
    assert.ok(
      Number(result.recommendedModelKw) >= Number(result.requiredKw) - 0.005,
      `area ${area}: size ${result.recommendedModelKw} below required ${result.requiredKw}`,
    );
  }
});
